INSERT INTO `t_stage` VALUES (1, 'pre_sale', '售前调研', '项目售前阶段的调研和评估', 'Search', '#52c41a', 'by_device', 1, 20, '[{\"id\": \"2503e508-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"site_survey\", \"name\": \"现场勘查\", \"description\": \"对项目现场进行实地勘查，了解现场环境和条件\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"site_photo\", \"name\": \"现场照片\", \"fileType\": \"image\", \"maxCount\": 10, \"minCount\": 1, \"required\": true}]}, {\"id\": \"2503e66f-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"requirement_analysis\", \"name\": \"需求分析\", \"description\": \"分析客户需求，确定技术方案\", \"defaultWeight\": 40, \"materialRequirements\": [{\"key\": \"requirement_doc\", \"name\": \"需求文档\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}, {\"id\": \"2503e756-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"proposal_design\", \"name\": \"方案设计\", \"description\": \"根据需求分析结果，设计技术实施方案\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"proposal_doc\", \"name\": \"方案文档\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}]', 1, 1, 0, NULL, '2026-03-26 18:15:49', 0, '2026-03-31 15:36:19');
INSERT INTO `t_stage` VALUES (2, 'preparation', '准备阶段', '施工前的准备工作', 'Setup', '#1890ff', 'by_task', 1, 20, '[{\"id\": null, \"key\": \"device_check\", \"name\": \"设备清单确认\", \"description\": \"确认项目所需的设备清单和规格\", \"defaultWeight\": null, \"materialRequirements\": []}, {\"id\": null, \"key\": \"construction_plan\", \"name\": \"施工方案制定\", \"description\": \"制定详细的施工计划和实施方案\", \"defaultWeight\": null, \"materialRequirements\": []}, {\"id\": null, \"key\": \"material_prepare\", \"name\": \"材料准备\", \"description\": \"准备施工所需的材料和工具\", \"defaultWeight\": null, \"materialRequirements\": []}]', 2, 1, 0, NULL, '2026-03-26 18:15:49', 0, '2026-03-31 15:20:42');
INSERT INTO `t_stage` VALUES (3, 'construction', '施工阶段', '设备安装和施工', 'Build', '#722ed1', 'by_device', 1, 30, '[{\"id\": \"251b4ebe-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"device_install\", \"name\": \"设备安装\", \"description\": \"按照设计方案进行设备安装\", \"defaultWeight\": 40, \"materialRequirements\": [{\"key\": \"install_photo\", \"name\": \"安装照片\", \"fileType\": \"image\", \"maxCount\": 20, \"minCount\": 1, \"required\": true}]}, {\"id\": \"251b4fc6-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"cable_laying\", \"name\": \"线路敷设\", \"description\": \"进行网络和电源线路的敷设\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"cable_photo\", \"name\": \"线路照片\", \"fileType\": \"image\", \"maxCount\": 10, \"minCount\": 1, \"required\": true}]}, {\"id\": \"251b508d-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"device_debug\", \"name\": \"设备调试\", \"description\": \"对安装的设备进行初步调试\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"debug_report\", \"name\": \"调试报告\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}]', 3, 1, 0, NULL, '2026-03-26 18:15:49', NULL, '2026-03-30 13:56:07');
INSERT INTO `t_stage` VALUES (4, 'configuration', '配置阶段', '设备配置和调试', 'Setting', '#fa8c16', 'by_device', 1, 30, '[{\"id\": \"25331e16-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"param_config\", \"name\": \"参数配置\", \"description\": \"配置设备的运行参数\", \"defaultWeight\": 35, \"materialRequirements\": [{\"key\": \"param_list\", \"name\": \"参数清单\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}, {\"id\": \"25331f22-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"network_config\", \"name\": \"网络配置\", \"description\": \"配置网络连接和通信参数\", \"defaultWeight\": 35, \"materialRequirements\": [{\"key\": \"network_config\", \"name\": \"网络配置表\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}, {\"id\": \"25331ffa-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"function_test\", \"name\": \"功能测试\", \"description\": \"测试设备各项功能是否正常\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"test_report\", \"name\": \"测试报告\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}]', 4, 1, 0, NULL, '2026-03-26 18:15:49', NULL, '2026-03-30 13:56:07');
INSERT INTO `t_stage` VALUES (5, 'verification', '核对阶段', '数据核对和验证', 'CheckCircle', '#13c2c2', 'by_device', 1, 20, '[{\"id\": \"2540a695-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"data_verification\", \"name\": \"数据核对\", \"description\": \"核对采集的数据是否准确完整\", \"defaultWeight\": 50, \"materialRequirements\": [{\"key\": \"data_sample\", \"name\": \"数据样本\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}, {\"id\": \"2540a79d-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"report_generate\", \"name\": \"报表生成\", \"description\": \"生成数据核对报表\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"verification_report\", \"name\": \"核对报表\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}, {\"id\": \"2540a9aa-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"issue_fix\", \"name\": \"问题修复\", \"description\": \"修复核对过程中发现的问题\", \"defaultWeight\": 20, \"materialRequirements\": []}]', 5, 1, 0, NULL, '2026-03-26 18:15:49', NULL, '2026-03-30 13:56:07');
INSERT INTO `t_stage` VALUES (6, 'acceptance', '验收阶段', '项目验收和交付', 'CheckSquare', '#52c41a', 'by_task', 1, 0, '[{\"id\": \"254ae7e8-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"acceptance_test\", \"name\": \"验收测试\", \"description\": \"进行项目验收测试\", \"defaultWeight\": 40, \"materialRequirements\": [{\"key\": \"acceptance_report\", \"name\": \"验收报告\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}, {\"id\": \"254ae909-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"doc_delivery\", \"name\": \"文档交付\", \"description\": \"整理并交付项目相关文档\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"project_docs\", \"name\": \"项目文档\", \"fileType\": \"document\", \"maxCount\": 10, \"minCount\": 1, \"required\": true}]}, {\"id\": \"254ae9dc-2bfd-11f1-9553-863c8dd492fe\", \"key\": \"training\", \"name\": \"用户培训\", \"description\": \"对用户进行系统使用培训\", \"defaultWeight\": 30, \"materialRequirements\": [{\"key\": \"training_material\", \"name\": \"培训材料\", \"fileType\": \"document\", \"maxCount\": 1, \"minCount\": 1, \"required\": true}]}]', 6, 1, 0, NULL, '2026-03-26 18:15:49', 0, '2026-03-31 15:20:49');



